formulas.expression:
IF(OR(ISBLANK({!$Record.Ship_To_Account__r.Annual_Print_Statement_Volume__c})
),
' "Annual Print Statement Volume" field on the "' & {!$Record.Ship_To_Account__r.Name} & '" Account.',
''
)

IF(OR(ISBLANK({!Find_products_with_ARR_required_fields.BPS_Upcharge__c})
),
' "BPS Upcharge" field on the "' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & '" Quote Line.',
''
)

IF(OR(
{!Find_products_with_ARR_required_fields.Ship_To_Account__r.ShippingCountry} = 'Canada',
{!Find_products_with_ARR_required_fields.Ship_To_Account__r.ShippingCountry} = 'United Kingdom'
),
IF(OR(ISBLANK({!Find_products_with_ARR_required_fields.Avg_FX_Trans_Amt__c})),
' "Avg FX Trans Amt" field on the "' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & '" Quote Line.',
''
),
''
)

IF(OR(
{!Find_products_with_ARR_required_fields.Ship_To_Account__r.ShippingCountry} = 'Canada',
{!Find_products_with_ARR_required_fields.Ship_To_Account__r.ShippingCountry} = 'United Kingdom'
),
IF(OR(ISBLANK({!Find_products_with_ARR_required_fields.Client_Home_CCY_XB_PYMNTS__c})),
' "Client Home CCY XB PYMNTS" field on the "' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & '" Quote Line.',
''
),
''
)

IF(OR(
{!Find_products_with_ARR_required_fields.Ship_To_Account__r.ShippingCountry} = 'Canada',
{!Find_products_with_ARR_required_fields.Ship_To_Account__r.ShippingCountry} = 'United Kingdom'
),
IF(OR(ISBLANK({!Find_products_with_ARR_required_fields.DOM_Outgoing_PYMTS__c})),
' "# DOM Outgoing PYMTS" field on the "' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & '" Quote Line.',
''
),
''
)

IF(
    AND(
        {!Find_products_with_ARR_required_fields.Requires_ARR_Fields_Completion__c} = true,
        AND(
            ISPICKVAL({!Find_products_with_ARR_required_fields.Surcharging__c}, "Yes"),
            OR(
                AND(
                    ISPICKVAL({!Find_products_with_ARR_required_fields.Usage_Type__c}, "Amount"),
                    OR(
                        ISBLANK({!Find_products_with_ARR_required_fields.Annual_No_Surcharge_Transactions__c})
                    )
                ),
                AND(
                    OR(
                        ISPICKVAL({!Find_products_with_ARR_required_fields.Usage_Type__c}, "Percent"),
                        ISPICKVAL({!Find_products_with_ARR_required_fields.Usage_Type__c}, "Both")
                    ),
                    OR(
                        ISBLANK({!Find_products_with_ARR_required_fields.Annual_Total_Surcharge_Volume__c})
                    )
                )
            )
        )
    ),
    IF(
        ISPICKVAL({!Find_products_with_ARR_required_fields.Usage_Type__c}, "Amount"),
        IF(
            AND(
                ISPICKVAL({!Find_products_with_ARR_required_fields.Surcharging__c}, "Yes"),
                OR(
                    ISBLANK({!Find_products_with_ARR_required_fields.Annual_No_Surcharge_Transactions__c})
                )
            ),
            '"Annual # Surcharge Transactions" field on this Quote Line.',
            ""
        ),
        IF(
            AND(
                ISPICKVAL({!Find_products_with_ARR_required_fields.Surcharging__c}, "Yes"),
                OR(
                    ISBLANK({!Find_products_with_ARR_required_fields.Annual_Total_Surcharge_Volume__c})
                )
            ),
            '"Annual Total Surcharge Volume" field on this Quote Line.',
            ""
        )
    ),
    ""
)

IF(
    AND(
        {!Find_products_with_ARR_required_fields.Requires_ARR_Fields_Completion__c} = true,
        OR(
            AND(
                ISPICKVAL({!Find_products_with_ARR_required_fields.Usage_Type__c}, "Amount"),
                OR(
                    ISBLANK({!Find_products_with_ARR_required_fields.Annual_Number_of_Domestic_Transactions__c})
                )
            ),
            AND(
                OR(
                    ISPICKVAL({!Find_products_with_ARR_required_fields.Usage_Type__c}, "Percent"),
                    ISPICKVAL({!Find_products_with_ARR_required_fields.Usage_Type__c}, "Both")
                ),
                OR(
                    ISBLANK({!Find_products_with_ARR_required_fields.Annual_Total_CC_Volume__c})
                )
            )
        )
    ),
    IF(
        ISPICKVAL({!Find_products_with_ARR_required_fields.Usage_Type__c}, "Amount"),
        IF(
            OR(
                ISBLANK({!Find_products_with_ARR_required_fields.Annual_Number_of_Domestic_Transactions__c})
            ),
             ' "Annual # of Domestic Transactions" field on the "' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & '" Quote Line.',
            ""
        ),
        IF(
            OR(
                ISBLANK({!Find_products_with_ARR_required_fields.Annual_Total_CC_Volume__c})
            ),
             ' "Annual Total Domestic Volume" field on the ' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & ' Quote Line.',
            ""
        )
    ),
    ""
)

IF(
    AND(
        {!Find_products_with_ARR_required_fields.Requires_ARR_Fields_Completion__c} = true,
        OR(
            ISBLANK({!Find_products_with_ARR_required_fields.No_International_Payers__c})
        )
    ),
    ' "No. International Payers" field on the "' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & '" Quote Line.',
    ''
)

IF(OR(ISBLANK({!Find_products_with_ARR_required_fields.No_Processed_Volume__c})
),
' "# Processed Volume" field on the "' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & '" Quote Line.',
''
)

IF(OR(ISBLANK({!Find_products_with_ARR_required_fields.Processed_Volume_Amount__c})
),
' "Processed Volume Amount" field on the "' & {!Find_products_with_ARR_required_fields.SBQQ__ProductName__c} & '" Quote Line.',
''
)
